+const int _kExhaustiveMeasurementLimit = 1024;
 // תווי בקרה דורשים פסקה עצמאית כדי שלא ישפיעו על מדידת תוויות אחרות.
 final _independentParagraphLabel = RegExp(
   r'[\p{C}\p{Zl}\p{Zp}\u{10000}-\u{10ffff}]',
@@ -189,8 +190,16 @@ double calculateAppMenuPreferredWidth<T>(
   );

   final labels = entries.map((entry) => entry.label).toSet().toList();
+  // ברשימת ענק (כל שורות ספר) מודדים מהארוכה לקצרה ועוצרים כשאורך × התו
+  // הרחב ביותר כבר לא יכול לעלות על המקסימום. 10% מרווח מכסים קרנינג חיובי.
+  var maxCharWidth = double.infinity;
+  if (labels.length > _kExhaustiveMeasurementLimit) {
+    maxCharWidth = _maxCharWidth(labels, textStyle) * 1.1;
+    labels.sort((a, b) => b.length.compareTo(a.length));
+  }
   var maxLabelWidth = 0.0;
   for (var start = 0; start < labels.length; start += _kLabelsPerMeasurement) {
+    if (labels[start].length * maxCharWidth <= maxLabelWidth) break;
     final end = min(start + _kLabelsPerMeasurement, labels.length);
     final batch = labels.sublist(start, end);
     final paragraphs = <String>[];
@@ -243,6 +252,25 @@ double calculateAppMenuPreferredWidth<T>(
   return max(metrics.menuMinWidth, maxLabelWidth + occupiedWidth);
 }

+/// רוחב התו הרחב ביותר בתוויות, או אינסוף כשיש תו בקרה (טאב וכד')
+/// שרוחבו הבודד אינו חוסם את רוחבו בתוך שורה.
+double _maxCharWidth(List<String> labels, TextStyle style) {
+  final runes = <int>{for (final label in labels) ...label.runes};
+  var widest = 0.0;
+  for (final rune in runes) {
+    final char = String.fromCharCode(rune);
+    if (_independentParagraphLabel.hasMatch(char)) return double.infinity;
+    final painter = TextPainter(
+      text: TextSpan(text: char, style: style),
+      textDirection: TextDirection.rtl,
+      maxLines: 1,
+    )..layout();
+    widest = max(widest, painter.width);
+    painter.dispose();
+  }
+  return widest;
+}
