+import 'dart:convert';
+import 'dart:io';
+import 'dart:ui' as ui;
+
+import 'package:flutter/material.dart';
+import 'package:flutter/rendering.dart';
+import 'package:flutter/services.dart';
+import 'package:flutter_localizations/flutter_localizations.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:otzaria/theme/theme_exports.dart';
+import 'package:otzaria/widgets/misc/app_menu_exports.dart';
+
+void main() {
+  TestWidgetsFlutterBinding.ensureInitialized();
+
+  setUpAll(() async {
+    final manifest = jsonDecode(
+      await rootBundle.loadString('FontManifest.json'),
+    ) as List<dynamic>;
+    for (final font in manifest.cast<Map<String, dynamic>>()) {
+      final family = font['family'] as String;
+      if (!family.contains('Fluent') && !family.contains('OtzariaIcons')) {
+        continue;
+      }
+      final loader = FontLoader(family);
+      for (final face
+          in (font['fonts'] as List<dynamic>).cast<Map<String, dynamic>>()) {
+        loader.addFont(rootBundle.load(face['asset'] as String));
+      }
+      await loader.load();
+    }
+    await (FontLoader(
+      'Roboto',
+    )..addFont(rootBundle.load('fonts/Rubik-VariableFont_wght.ttf'))).load();
+  });
+
+  testWidgets('צילום בורר עברי לאחר התייצבות התפריט', (tester) async {
+    await tester.binding.setSurfaceSize(const Size(900, 680));
+    addTearDown(() => tester.binding.setSurfaceSize(null));
+    final boundaryKey = GlobalKey();
+    final entries = [
+      for (var i = 0; i < 1000; i++) AppMenuEntry(value: i, label: 'שורה $i'),
+    ];
+    await tester.pumpWidget(
+      RepaintBoundary(
+        key: boundaryKey,
+        child: MaterialApp(
+          locale: const Locale('he'),
+          supportedLocales: const [Locale('he')],
+          localizationsDelegates: GlobalMaterialLocalizations.delegates,
+          theme: AppThemeData.light(
+            AppThemeData.createColorScheme(
+              AppSeedColors.blue,
+              Brightness.light,
+            ),
+            compactMenuMode: false,
+          ),
+          home: Scaffold(
+            body: Center(
+              child: SizedBox(
+                width: 300,
+                child: AppDropdownField<int>(
+                  value: 900,
+                  entries: entries,
+                  enableSearch: true,
+                  decoration: const InputDecoration(labelText: 'עד'),
+                  filterLabels: const ['הכל', 'זוגיים'],
+                  filterPredicates: [null, (entry) => entry.value.isEven],
+                  initialFilter: 1,
+                  onSelected: (_) {},
+                ),
+              ),
+            ),
+          ),
+        ),
+      ),
+    );
+    await tester.tap(find.byType(AppDropdownField<int>));
+    await tester.pumpAndSettle();
+    expect(find.byType(EditableText), findsOneWidget);
+    final list = find.byType(ListView);
+    expect(
+      find.descendant(of: list, matching: find.text('שורה 900')),
+      findsOneWidget,
+    );
+    expect(tester.takeException(), isNull);
+
+    final boundary = tester.renderObject<RenderRepaintBoundary>(
+      find.byKey(boundaryKey),
+    );
+    await tester.runAsync(() async {
+      final image = await boundary.toImage(pixelRatio: 1);
+      try {
+        final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
+        final output = File(
+          const String.fromEnvironment('UI_MENU_CAPTURE_OUT'),
+        );
+        await output.parent.create(recursive: true);
+        await output.writeAsBytes(bytes!.buffer.asUint8List());
+      } finally {
+        image.dispose();
+      }
+    });
+  });
+}
